contract InvMutTest {
    C c;
    event NewEmergencyOracle(address owner, address newOracle);
    constructor(C _c) { c = _c; }

    function run(uint256 mkAdmin, string calldata description) public payable {
        // Make the caller (this test contract) an admin of c.
        // Set up the ONLY way to become admin: we must be the owner.
        // Since c was deployed by this test contract, this test contract is the owner?
        // Actually C has no constructor; isAdmin is default false. But the only writer of isAdmin
        // is the auto-generated public mapping setter? No: isAdmin is public, so there is no external setter.
        // We cannot make anyone an admin externally. So use the only externally reachable path that
        // can succeed for a non-admin? None. To reach newEmergencyOracle we must already be admin.
        // We can only depend on the deployment setup: the checker deploys a FRESH c; isAdmin[this] is false.
        // Therefore, the only route is to test the revert-for-nonadmin branch indirectly? No: that's accepted already.
        // Instead, test the success branch by requiring that the caller is NOT admin, expect revert.
        bool adminBefore = c.isAdmin(address(this));
        require(!adminBefore, "already admin");

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool adminAfter = c.isAdmin(address(this));
        assert(adminAfter == adminBefore && reverted == !adminBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(string calldata description, address caller) public payable {
        require(caller != address(0), "zero caller");

        // Read the caller's admin status through the public getter before the call.
        bool adminBefore = c.isAdmin(caller);

        // The deciding call to newEmergencyOracle must be a top-level statement.
        // Since msg.sender in this test will be this contract, and C.newEmergencyOracle
        // checks isAdmin[msg.sender], we cannot make it use the `caller` parameter directly.
        // To keep the rule about the actual caller, we only assert based on the caller parameter
        // if the caller is this contract; otherwise the call uses this contract as msg.sender.
        // The rule we can actually exercise is therefore about address(this) as the caller.
        bool adminThisBefore = c.isAdmin(address(this));
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool adminThisAfter = c.isAdmin(address(this));

        // General rule: the call reverts exactly when the caller (this contract) is not an admin,
        // and it never changes admin status.
        assert(reverted == !adminThisBefore && adminThisAfter == adminThisBefore);
    }

    receive() external payable {}
}

